/* ---------- batch five ---------- */
.ch{padding:0}
.ch-head{display:flex;align-items:flex-start;justify-content:space-between;gap:12px;padding:14px 16px 10px}
.ch-val{display:flex;align-items:center;gap:10px;margin-top:4px;font-family:var(--mono);font-weight:700;font-size:26px;letter-spacing:-.5px}
.ch-legend{display:flex;gap:16px;padding:10px 16px 14px;font-size:12px;color:var(--text-dim)}
.ch-legend span{display:inline-flex;align-items:center;gap:6px}
.sw.dash{background:repeating-linear-gradient(90deg,var(--muted) 0 3px,transparent 3px 5px);height:2px;width:12px}
.ch-tip{position:absolute;top:6px;padding:6px 8px;background:var(--panel);border:1px solid var(--icon-line);font-size:12px;white-space:nowrap;opacity:0;transition:opacity .2s;pointer-events:none;z-index:2}
.ch-tip .mono-xs{display:block;font-size:10px}
.ch-tip b{font-family:var(--mono)}

/* bar chart */
.bc{display:flex;align-items:flex-end;gap:12px;height:200px;margin:6px 16px 0;padding-bottom:22px;position:relative;border-bottom:1px solid var(--line);background:linear-gradient(var(--line),var(--line)) 0 25%/100% 1px no-repeat,linear-gradient(var(--line),var(--line)) 0 50%/100% 1px no-repeat,linear-gradient(var(--line),var(--line)) 0 75%/100% 1px no-repeat}
.bc-col{position:relative;flex:1;height:100%;display:flex;align-items:flex-end;justify-content:center;gap:3px;cursor:pointer}
.bc-col .b{width:40%;height:0;transition:height .7s var(--ease),width .5s var(--ease),opacity .25s}
.bc-col .b.a{background:var(--accent)}
.bc-col .b.d{background:rgba(var(--fg-rgb),.35)}
.bc.stacked .bc-col{flex-direction:column-reverse;align-items:center;justify-content:flex-start;gap:0}
.bc.stacked .bc-col .b{width:60%}
.bc-col .lab{position:absolute;bottom:-20px;font-family:var(--mono);font-size:10px;color:var(--muted)}
.bc.hov .bc-col:not(.on) .b{opacity:.35}
.bc .ch-tip{top:-4px}

/* bar chart: no divider above the legend, range switcher in the header */
#c42 .bc{border-bottom:0}
#c42 .ch-legend{padding-top:14px}
.bc.dense{gap:6px}
.bc.dense .lab{font-size:10px}

/* ---------- bar chart ---------- */
{
  const bc = $('#bc');
  const ALL = 12, desAll = [96, 104, 118, 110, 126, 112, 120, 138, 150, 132, 164, 178], devAll = [70, 84, 80, 92, 98, 88, 90, 110, 96, 124, 140, 152];
  let n = 6, mode = 'grouped', shown = false, months = [], des = [], dev = [];
  function build(){
    months = Array.from({ length:n }, (_, i) => new Date(TODAY.getFullYear(), TODAY.getMonth() - n + 1 + i, 1).toLocaleDateString('en-GB', { month:'short' }));
    des = desAll.slice(ALL - n); dev = devAll.slice(ALL - n);
    bc.innerHTML = months.map((m, i) => `<div class="bc-col" data-i="${i}"><span class="b a"></span><span class="b d"></span><span class="lab">${n === 12 && i % 2 ? '' : m}</span></div>`).join('') + '<div class="ch-tip" id="bc-tip"></div>';
    bc.classList.toggle('dense', n === 12);
    const tip = $('#bc-tip');
    $$('.bc-col', bc).forEach(c => {
      c.addEventListener('mouseenter', () => {
        const i = +c.dataset.i; bc.classList.add('hov'); $$('.bc-col', bc).forEach(x => x.classList.toggle('on', x === c));
        tip.innerHTML = `<span class="mono-xs">${months[i]}</span>Design <b>${des[i]} h</b><br>Development <b>${dev[i]} h</b>`;
        const r = bc.getBoundingClientRect(), cr = c.getBoundingClientRect(); const left = cr.left - r.left + cr.width / 2 - tip.offsetWidth / 2;
        tip.style.left = Math.max(0, Math.min(r.width - tip.offsetWidth, left)) + 'px'; tip.style.opacity = '1'; Sound.play('stream');
      });
      c.addEventListener('mouseleave', () => { bc.classList.remove('hov'); c.classList.remove('on'); tip.style.opacity = '0'; });
    });
  }
  function size(){
    const max = mode === 'grouped' ? Math.max(...des, ...dev) : Math.max(...des.map((v, i) => v + dev[i]));
    $$('.bc-col', bc).forEach((c, i) => { const [a, d] = $$('.b', c); a.style.height = shown ? (des[i] / max * 92) + '%' : '0'; d.style.height = shown ? (dev[i] / max * 92) + '%' : '0'; });
  }
  const total = () => countTo($('#bc-total'), des.concat(dev).reduce((a, b) => a + b, 0), { dur:900 });
  tabHandlers.bars = v => { mode = v; bc.classList.toggle('stacked', v === 'stacked'); size(); };
  segInit($('#bc-seg'), v => { n = +v; build(); requestAnimationFrame(() => requestAnimationFrame(size)); total(); });
  build(); size();
  whenSeen($('#c42'), () => { shown = true; size(); total(); ambient('c42', 'pop'); });
}
